365	    return money((this.patronIdsByPerson().get(personId) ?? []).reduce((sum, id) => sum + (due.get(id) ?? 0), 0));
366	  }
367	
368	  /** Name the chosen person as the person's patron; refused when it is themselves or already their patron. */
369	  protected addPatron(p: PersonView, patronId: string): void {
370	    if (this.addingPatron() === p.id) return;
371	    this.personError.set(null);
372	    this.patronError.set(null);
373	    const sheet = this.sheets.current();
374	    if (!sheet || patronId === '') return;
375	    this.addingPatron.set(p.id);
376	    this.patronsApi.add(sheet.id, p.id, Number(patronId)).subscribe({
377	      next: (added) => {
378	        this.addingPatron.set(null);
379	        this.patrons.update((list) => [...list, added]);
380	      },
381	      error: (err: unknown) => {
382	        this.addingPatron.set(null);
383	        this.patronError.set({
384	          id: p.id,
385	          message:
386	            err instanceof HttpErrorResponse && err.status === 422
387	              ? p.name + ' cannot be their own patron.'
388	              : err instanceof HttpErrorResponse && err.status === 409
389	                ? 'That person is already a patron of ' + p.name + '.'
390	                : 'Could not add that patron.',
391	        });
392	      },
393	    });
394	  }
395	
396	  protected overdueOf(personId: number): Overdue {
397	    return this.overdueByPerson().get(personId) ?? NO_OVERDUE;
398	  }
399	
400	  protected statementOf(personId: number): StatementSummary | undefined {
401	    return this.statements().get(personId);
402	  }
403	
404	  /** Take a statement of the person, then show their summary and their claims as it left them. */
405	  protected takeStatement(p: PersonView): void {
406	    if (this.stating() === p.id) return;
407	    this.personError.set(null);
408	    this.patronError.set(null);
409	    const sheet = this.sheets.current();
410	    if (!sheet) return;
411	    this.stating.set(p.id);
412	    this.statementsApi.take(sheet.id, p.id).subscribe({
413	      next: ({ summary, claims }) => {
414	        this.stating.set(null);
415	        this.statements.update((map) => new Map(map).set(summary.personId, summary));
416	        const byId = new Map(claims.map((c) => [c.id, c]));
417	        this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
418	      },
419	      error: () => {
420	        this.stating.set(null);
421	        this.personError.set({ id: p.id, message: 'Could not take a statement of ' + p.name + '.' });
422	      },
423	    });
424	  }
425	
426	  /** Retire the person from a date; a blank date takes the sheet's today. */
427	  protected retire(p: PersonView, from: string): void {
428	    if (this.retiring() === p.id) return;
429	    this.personError.set(null);
430	    this.patronError.set(null);
431	    const sheet = this.sheets.current();
432	    if (!sheet) return;
433	    this.retiring.set(p.id);
434	    this.api.retire(sheet.id, p.id, from === '' ? null : from).subscribe({
435	      next: (retired) => {
436	        this.retiring.set(null);
437	        this.people.update((list) => list.map((q) => (q.id === retired.id ? retired : q)));
438	      },
439	      error: () => {
440	        this.retiring.set(null);
441	        this.personError.set({ id: p.id, message: 'Could not retire ' + p.name + '.' });
442	      },
443	    });
444	  }
445	
446	  /** Put the person on hold, or take them off hold when held. */
447	  protected toggleHold(p: PersonView): void {
448	    if (this.holding() === p.id) return;
449	    this.personError.set(null);
450	    this.patronError.set(null);
451	    const sheet = this.sheets.current();
452	    if (!sheet) return;
453	    this.holding.set(p.id);
454	    this.api.toggleHold(sheet.id, p.id).subscribe({
455	      next: (saved) => {
456	        this.holding.set(null);
457	        this.people.update((list) => list.map((q) => (q.id === saved.id ? saved : q)));
458	      },
459	      error: () => {
460	        this.holding.set(null);
461	        this.personError.set({ id: p.id, message: 'Could not ' + (p.held ? 'release ' : 'hold ') + p.name + '.' });
462	      },
463	    });
464	  }
465	
466	  protected claimSaved(saved: ClaimView): void {
467	    this.claims.update((list) =>
468	      list.some((c) => c.id === saved.id)
469	        ? list.map((c) => (c.id === saved.id ? saved : c))
470	        : [saved, ...list].sort((a, b) => b.id - a.id),
471	    );
472	  }
473	
474	  /** Quick-add a DRAFT claim for the named person, adding them first (grade A) when not on the sheet. */
475	  protected quickAdd(): void {
476	    // A second submit before the first has answered is ignored, so it stores one record.
477	    if (this.quickSaving()) return;
478	    this.quickError.set(null);
479	    const sheet = this.sheets.current();
480	    if (!sheet) return;
481	    const value = this.quickForm.getRawValue();
482	    if (value.name.trim() === '') {
483	      this.quickError.set('Type a name for the person.');
484	      return;
485	    }
486	    const amount = value.amount.trim();
487	    if (!AMOUNT_PATTERN.test(amount)) {
488	      this.quickError.set('Type an amount of 0.00 or more, with up to two decimals.');
489	      return;
490	    }
491	    this.quickSaving.set(true);
492	    this.claimsApi.quickAdd(sheet.id, value.name, amount).subscribe({
493	      next: ({ person, personAdded, claim }) => {
494	        this.quickSaving.set(false);
495	        if (personAdded) this.people.update((list) => [...list, person]);
496	        this.claimSaved(claim);
497	        this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
498	      },
499	      error: (err: unknown) => {
500	        this.quickSaving.set(false);
501	        this.quickError.set(
502	          err instanceof HttpErrorResponse && err.status === 423
503	            ? 'That claim is dated inside a closed period.'
504	            : err instanceof HttpErrorResponse && err.status === 422
505	              ? 'That claim is dated after the person retired.'
506	            : err instanceof HttpErrorResponse && err.status === 409
507	              ? 'That name is already in use on this sheet.'
508	              : 'Could not add that claim.',
509	        );
510	      },
511	    });
512	  }
513	
514	  protected edit(p: PersonView): void {
515	    this.personError.set(null);
516	    this.patronError.set(null);
517	    this.editingId.set(p.id);
518	    this.editingVersion = p.version;
519	    this.form.setValue({ name: p.name, grade: this.gradeToday(p), gradeFrom: '' }, { emitEvent: false });
520	    this.error.set(null);
521	  }
522	
523	  protected reset(): void {
524	    this.editingId.set(null);
525	    this.form.reset({ name: '', grade: 'A', gradeFrom: '' }, { emitEvent: false });
526	    this.error.set(null);
527	  }
528	
529	  protected submit(): void {
530	    // A second submit before the first has answered is ignored, so it stores one record.
531	    if (this.saving()) return;
532	    this.error.set(null);
533	    const sheet = this.sheets.current();
534	    if (!sheet) return;
535	    const value = this.form.getRawValue();
536	    if (value.name.trim() === '') {
537	      this.error.set('Type a name for the person.');
538	      return;
539	    }
540	    const id = this.editingId();
541	    this.saving.set(true);
542	    const request = id === null
543	      ? this.api.add(sheet.id, { name: value.name, grade: value.grade })
544	      : this.api.update(sheet.id, id, this.editingVersion,
545	          { name: value.name, grade: value.grade, gradeFrom: value.gradeFrom === '' ? null : value.gradeFrom });
546	    request.subscribe({
547	      next: (saved) => {
548	        this.saving.set(false);
549	        this.people.update((list) =>
550	          id === null ? [...list, saved] : list.map((p) => (p.id === saved.id ? saved : p)),
551	        );
552	        this.reset();
553	      },
554	      error: (err: unknown) => {
555	        this.saving.set(false);
556	        if (id !== null && err instanceof HttpErrorResponse && err.status === 412) {
557	          this.error.set('Someone else has saved this person since you opened it; their values are shown.');
558	          this.showCurrent(sheet.id, id);
559	        } else if (err instanceof HttpErrorResponse && err.status === 409) {
560	          this.error.set('That name is already in use on this sheet.');
561	        } else {
562	          this.error.set(id === null ? 'Could not add that person.' : 'Could not save that person.');
563	        }
564	      },
565	    });
566	  }
567	
568	  /** Re-read the people after a refused edit and show the person's current values in the editor. */
569	  private showCurrent(sheetId: string, id: number): void {
570	    this.api.list(sheetId).subscribe({
571	      next: (people) => {
572	        this.people.set(people);
573	        const current = people.find((p) => p.id === id);
574	        if (current && this.editingId() === id) {
575	          this.editingVersion = current.version;
576	          this.form.setValue({ name: current.name, grade: this.gradeToday(current), gradeFrom: '' }, { emitEvent: false });
577	        }
578	      },
579	    });
580	  }
581	}
